const staticData = $getWorkflowStaticData('global');

// 1. Ekstraksi isi pesan WhatsApp dari berbagai format input (Chatery / Switch / Webhook)
const content = String(
  $json.data?.content ||
  $json.body?.message?.text ||
  $json.body?.message?.conversation ||
  $json.body?.text ||
  $json.text ||
  $json.message ||
  $('Switch1')?.item?.json?.data?.content ||
  $('Switch1')?.item?.json?.body?.message?.text ||
  ''
).trim();

// Pastikan inisialisasi state tersimpan di n8n
staticData.devices = staticData.devices || {};
staticData.pendingCommands = staticData.pendingCommands || {};

// ================= PEMBERSIHAN OTOMATIS (PRUNING KEDALUWARSA) =================
// Hapus perangkat yang tidak mengirim update lebih dari 30 menit atau tidak punya stempel waktu
const now = Date.now();
const MAX_INACTIVE_MS = 30 * 60 * 1000; // 30 menit batas kedaluwarsa

for (const k of Object.keys(staticData.devices)) {
  const d = staticData.devices[k];
  // Hapus jika PC lama tidak memiliki lastSeen (data lawas) atau sudah offline > 30 menit
  if (!d || !d.lastSeen || (now - d.lastSeen > MAX_INACTIVE_MS)) {
    delete staticData.devices[k];
  }
}

const parts = content.split(/\s+/);
const rawCmd = (parts[0] || '').toUpperCase();

// ================= URUTKAN NAMA PC SECARA TERATUR =================
// Natural sort: 7309_0 -> 7309_1 -> 7309_2 -> 7309_3 -> 7309_4 -> 7309_5 -> 7309_6
const devKeys = Object.keys(staticData.devices || {}).sort((a, b) => 
  a.localeCompare(b, undefined, { numeric: true, sensitivity: 'base' })
);

let targetPc = '';
let nextArgIndex = 1;

// 2. Deteksi Target PC (Mendukung: "1", "7309_0", "PC 1", "LAPTOP 1", tautan langsung, atau "SEMUA")
if (parts[1]) {
  const p1 = parts[1].toUpperCase();

  // Jika parameter kedua langsung berupa tautan kuesioner FASIH
  if (parts[1].startsWith('http://') || parts[1].startsWith('https://')) {
    targetPc = 'SEMUA';
    nextArgIndex = 1;
  }
  // Jika perintah broadcast eksplisit
  else if (p1 === 'SEMUA' || p1 === 'ALL') {
    targetPc = 'SEMUA';
    nextArgIndex = 2;
  }
  // Jika format menggunakan prefix nama: "PC 1", "LAPTOP 2", dsb
  else if ((p1 === 'PC' || p1 === 'LAPTOP' || p1 === 'KOMPUTER' || p1 === 'NO') && parts[2]) {
    targetPc = `${p1} ${parts[2].toUpperCase()}`;
    nextArgIndex = 3;
  }
  // Jika nama PC langsung (misal: "7309_0", "1", "SERVER", dsb)
  else {
    targetPc = parts[1];
    nextArgIndex = 2;
  }
}

// 3. Pencocokan Cerdas dengan Daftar PC yang Sedang Aktif di n8n
let resolvedDeviceKey = null;

if (targetPc && targetPc !== 'SEMUA') {
  const cleanTarget = targetPc.toUpperCase().replace(/[\s\-_]/g, '');
  const targetDigits = targetPc.replace(/\D/g, '');

  // a. Cocok persis (misal: "7309_0" == "7309_0" atau "PC 1" == "PC 1")
  resolvedDeviceKey = devKeys.find(k => k.toUpperCase() === targetPc.toUpperCase());

  // b. Cocok tanpa spasi / tanda strip (misal: "73090" vs "7309_0")
  if (!resolvedDeviceKey) {
    resolvedDeviceKey = devKeys.find(k => k.toUpperCase().replace(/[\s\-_]/g, '') === cleanTarget);
  }

  // c. Cocok hanya nomor digit atau akhiran (misal user ketik "0", cocok ke "7309_0" atau "PC 0")
  if (!resolvedDeviceKey && targetDigits) {
    resolvedDeviceKey = devKeys.find(k => 
      k.replace(/\D/g, '') === targetDigits || 
      k.endsWith(`_${targetDigits}`) || 
      k.endsWith(` ${targetDigits}`)
    );
  }

  // d. Fallback: jika belum ada di devKeys, tetap gunakan nama yang diketik user
  if (!resolvedDeviceKey) {
    resolvedDeviceKey = targetPc;
  }
}

let reply = '';

// ================= DAFTAR PERINTAH BOT =================

// 1. PANDUAN LENGKAP (#QUERY / #HELP / #BANTUAN)
if (rawCmd === '#QUERY' || rawCmd === '#HELP' || rawCmd === '#BANTUAN' || rawCmd === '#MENU' || rawCmd === '#PANDUAN') {
  reply = '🤖 *[PANDUAN PERINTAH BOT TUNTAS SE2026]*\n\n' +
    'Gunakan perintah berawalan *#* berikut untuk memantau & mengendalikan bot di PC/Laptop:\n\n' +
    '📊 *1. CEK STATUS & MONITORING*\n' +
    '• *#STATUS* : Cek ringkasan status SEMUA PC aktif (berurutan)\n' +
    '• *#STATUS [Nama PC]* : Cek detail antrian PC tertentu (contoh: *#STATUS 7309_0* atau *#STATUS 0*)\n\n' +
    '🔄 *2. ULANGI BARIS GAGAL (RETRY)*\n' +
    '• *#ULANG* : Ulangi HANYA baris GAGAL pada PC yang mengalami error\n' +
    '• *#ULANG [Nama PC]* : Ulangi baris GAGAL khusus di PC tertentu (contoh: *#ULANG 7309_0* atau *#ULANG 0*)\n\n' +
    '⏸️ *3. PENGENDALIAN REMOTE*\n' +
    '• *#JEDA* : Menjeda proses di SEMUA PC\n' +
    '• *#JEDA [Nama PC]* : Menjeda proses hanya di PC yang dipilih\n' +
    '• *#LANJUT* : Melanjutkan proses di SEMUA PC\n' +
    '• *#LANJUT [Nama PC]* : Melanjutkan proses hanya di PC yang dipilih\n' +
    '• *#STOP* : Menghentikan total antrian di SEMUA PC\n' +
    '• *#STOP [Nama PC]* : Menghentikan proses hanya di PC yang dipilih\n\n' +
    '➕ *4. TAMBAH ANTRIAN LINK BARU*\n' +
    '• *#TAMBAH [link]* : Masukkan link ke antrian semua PC\n' +
    '• *#TAMBAH [Nama PC] [link]* : Masukkan link khusus ke PC tertentu\n\n' +
    '🧹 *5. BERSIHKAN MONITORING*\n' +
    '• *#BERSIHKAN* : Hapus riwayat PC lama yang sudah offline\n\n' +
    '💡 _Catatan: Format target PC fleksibel, bisa angka saja (#ULANG 0) atau nama lengkap (#ULANG 7309_0)._';
}
// 2. CEK STATUS & MONITORING (#STATUS / #CEK)
else if (rawCmd === '#STATUS' || rawCmd === '#CEK') {
  if (resolvedDeviceKey && resolvedDeviceKey !== 'SEMUA') {
    const st = staticData.devices[resolvedDeviceKey];
    if (!st) {
      reply = `⚠️ *[STATUS BOT TUNTAS]*\nTidak ditemukan data untuk *${resolvedDeviceKey}*.\nPerangkat aktif saat ini: ${devKeys.length ? devKeys.join(', ') : 'Belum ada'}`;
    } else if (st.message) {
      reply = st.message;
    } else {
      reply = `📊 *[STATUS BOT TUNTAS | ${st.pc}]*\n` +
        `⚡ Status: *${st.statusLabel || st.status}*\n` +
        `📋 Menu: *${st.mode || '-'}*\n` +
        `📈 Progres: *${st.progress}* ${st.persen ? `(${st.persen})` : ''}\n` +
        `🏢 Usaha: ${st.nama_usaha || '-'}${st.no_baris && st.no_baris !== '-' ? ` (Baris #${st.no_baris})` : ''}\n` +
        `✅ Sukses: ${st.successCount || 0} | ❌ Gagal: ${st.failedCount || 0}${st.skippedCount ? ` | ⏩ Dilewati: ${st.skippedCount}` : ''}\n` +
        `⏳ Sisa Antrian: ${st.queueRemaining || 0}\n` +
        `📶 Server FASIH: ${st.serverHealth || 'Normal'}\n` +
        `⏰ Waktu: ${st.updatedAt || '-'}`;
    }
  } else {
    if (devKeys.length === 0) {
      reply = '⚠️ *[STATUS BOT TUNTAS]*\nBelum ada laporan dari PC/Laptop yang aktif (atau seluruh unit sedang offline).\nPastikan ekstensi TUNTAS aktif di browser.';
    } else if (devKeys.length === 1) {
      const st = staticData.devices[devKeys[0]];
      reply = st.message ? st.message : (
        `📊 *[STATUS BOT TUNTAS | ${st.pc}]*\n` +
        `⚡ Status: *${st.statusLabel || st.status}*\n` +
        `📋 Menu: *${st.mode || '-'}*\n` +
        `📈 Progres: *${st.progress}* ${st.persen ? `(${st.persen})` : ''}\n` +
        `🏢 Usaha: ${st.nama_usaha || '-'}${st.no_baris && st.no_baris !== '-' ? ` (Baris #${st.no_baris})` : ''}\n` +
        `✅ Sukses: ${st.successCount || 0} | ❌ Gagal: ${st.failedCount || 0}${st.skippedCount ? ` | ⏩ Dilewati: ${st.skippedCount}` : ''}\n` +
        `⏳ Sisa Antrian: ${st.queueRemaining || 0}\n` +
        `📶 Server FASIH: ${st.serverHealth || 'Normal'}\n` +
        `⏰ Waktu: ${st.updatedAt || '-'}`
      );
    } else {
      let msg = `📊 *[MONITORING SEMUA PERANGKAT TUNTAS]*\nTotal perangkat aktif: *${devKeys.length}*\n\n`;
      for (const k of devKeys) {
        const d = staticData.devices[k];
        msg += `💻 *${d.pc}* [${d.statusLabel || d.status}]\n` +
          `   • Menu: ${d.mode || '-'}\n` +
          `   • Progres: *${d.progress}* ${d.persen ? `(${d.persen})` : ''}\n` +
          `   • Hasil: ✅ ${d.successCount || 0} | ❌ ${d.failedCount || 0}${d.skippedCount ? ` | ⏩ ${d.skippedCount}` : ''}\n` +
          `   • Usaha: ${d.nama_usaha || '-'}\n` +
          `   • Server: ${d.serverHealth || 'Normal'}\n` +
          `   • Update: ${d.updatedAt || '-'}\n\n`;
      }
      msg += `_Ketik *#STATUS [Nama PC]* untuk cek detail unit tertentu._`;
      reply = msg.trim();
    }
  }
}
// 3. ULANGI BARIS GAGAL (#ULANG / #RETRY / #ULANGI_GAGAL)
else if (rawCmd === '#ULANG' || rawCmd === '#RETRY' || rawCmd === '#ULANGI_GAGAL' || rawCmd === '#RETRY_FAILED') {
  // Jika target PC spesifik disebutkan (misal: #ULANG 1 atau #ULANG 7309_1)
  if (resolvedDeviceKey && resolvedDeviceKey !== 'SEMUA') {
    const d = staticData.devices[resolvedDeviceKey];
    const fCount = Number(d?.failedCount || 0);
    staticData.pendingCommands[resolvedDeviceKey] = { action: 'RETRY_FAILED', by: 'WhatsApp' };
    reply = `🔄 *[ULANGI BARIS GAGAL]*\nPerintah untuk mengulang baris gagal dikirim khusus ke *${resolvedDeviceKey}*` +
      (fCount > 0 ? ` (${fCount} baris gagal akan diproses ulang).` : '.\n(Catatan: saat ini tercatat 0 baris gagal di unit ini).');
  } 
  // Jika perintah umum (#ULANG tanpa target PC)
  else {
    // Cari PC mana saja yang benar-benar memiliki baris gagal (>0)
    const failedDevices = devKeys.filter(k => {
      const d = staticData.devices[k];
      return d && Number(d.failedCount) > 0;
    });

    if (failedDevices.length === 0) {
      reply = '✅ *[TIDAK ADA BARIS GAGAL]*\nSeluruh PC/Laptop aktif saat ini *tidak memiliki baris antrian yang gagal* (semua baris sudah selesai/sukses).\n\nTidak ada antrian yang perlu diulang.';
    } else if (failedDevices.length === 1) {
      const targetPc = failedDevices[0];
      const fCount = staticData.devices[targetPc].failedCount;
      staticData.pendingCommands[targetPc] = { action: 'RETRY_FAILED', by: 'WhatsApp' };
      reply = `🔄 *[ULANGI BARIS GAGAL]*\nPerintah mengulang baris gagal dikirim *khusus ke ${targetPc}* (${fCount} baris gagal).\n\nUnit lain yang sudah sukses *tidak akan diulang*.`;
    } else {
      // Kirim perintah HANYA ke PC-PC yang memiliki baris gagal
      for (const targetPc of failedDevices) {
        staticData.pendingCommands[targetPc] = { action: 'RETRY_FAILED', by: 'WhatsApp' };
      }
      const listDev = failedDevices.map(k => `• *${k}*: ${staticData.devices[k].failedCount} baris gagal`).join('\n');
      reply = `🔄 *[ULANGI BARIS GAGAL]*\nPerintah mengulang baris gagal dikirim ke unit yang memiliki error:\n${listDev}\n\nUnit lain yang sudah sukses *tidak akan diulang*.`;
    }
  }
}
// 4. JEDA (#JEDA / #PAUSE)
else if (rawCmd === '#JEDA' || rawCmd === '#PAUSE') {
  if (resolvedDeviceKey && resolvedDeviceKey !== 'SEMUA') {
    staticData.pendingCommands[resolvedDeviceKey] = { action: 'PAUSE', by: 'WhatsApp' };
    reply = `⏸️ *[PERINTAH JEDA DIKIRIM]*\nPerintah jeda telah dikirim khusus untuk *${resolvedDeviceKey}*.`;
  } else {
    staticData.broadcastCommand = { id: Date.now(), action: 'PAUSE', by: 'WhatsApp', timestamp: Date.now() };
    reply = '⏸️ *[PERINTAH JEDA DIKIRIM]*\nPerintah jeda telah dikirim ke *SEMUA PC/Laptop* aktif.';
  }
}
// 5. LANJUT (#LANJUT / #RESUME)
else if (rawCmd === '#LANJUT' || rawCmd === '#RESUME') {
  if (resolvedDeviceKey && resolvedDeviceKey !== 'SEMUA') {
    staticData.pendingCommands[resolvedDeviceKey] = { action: 'RESUME', by: 'WhatsApp' };
    reply = `▶️ *[PERINTAH LANJUT DIKIRIM]*\nPerintah lanjut telah dikirim khusus untuk *${resolvedDeviceKey}*.`;
  } else {
    staticData.broadcastCommand = { id: Date.now(), action: 'RESUME', by: 'WhatsApp', timestamp: Date.now() };
    reply = '▶️ *[PERINTAH LANJUT DIKIRIM]*\nPerintah lanjut telah dikirim ke *SEMUA PC/Laptop* aktif.';
  }
}
// 6. STOP (#STOP / #BERHENTI)
else if (rawCmd === '#STOP' || rawCmd === '#BERHENTI') {
  if (resolvedDeviceKey && resolvedDeviceKey !== 'SEMUA') {
    staticData.pendingCommands[resolvedDeviceKey] = { action: 'STOP', by: 'WhatsApp' };
    reply = `⏹️ *[PERINTAH STOP DIKIRIM]*\nPerintah stop telah dikirim khusus untuk *${resolvedDeviceKey}*.`;
  } else {
    staticData.broadcastCommand = { id: Date.now(), action: 'STOP', by: 'WhatsApp', timestamp: Date.now() };
    reply = '⏹️ *[PERINTAH STOP DIKIRIM]*\nPerintah stop telah dikirim ke *SEMUA PC/Laptop* aktif.';
  }
}
// 7. TAMBAH ANTRIAN LINK (#TAMBAH)
else if (rawCmd === '#TAMBAH') {
  const linkCandidate = parts[nextArgIndex] || parts[1] || '';
  if (!linkCandidate.startsWith('http')) {
    reply = '⚠️ Format link tidak valid.\nContoh format yang benar:\n• *#TAMBAH https://fasih-sm.bps.go.id/...*\n• *#TAMBAH 1 https://fasih-sm.bps.go.id/...*';
  } else {
    const cmdPayload = { action: 'ADD_QUEUE', link: linkCandidate.trim() };
    if (resolvedDeviceKey && resolvedDeviceKey !== 'SEMUA') {
      staticData.pendingCommands[resolvedDeviceKey] = cmdPayload;
      reply = `➕ *[ANTRIAN DITAMBAHKAN]*\nTautan kuesioner baru dikirim khusus ke *${resolvedDeviceKey}*:\n${linkCandidate.trim()}`;
    } else {
      staticData.broadcastCommand = { id: Date.now(), action: 'ADD_QUEUE', link: linkCandidate.trim(), timestamp: Date.now() };
      reply = `➕ *[ANTRIAN DITAMBAHKAN]*\nTautan kuesioner baru dikirim ke antrian *SEMUA PC*:\n${linkCandidate.trim()}`;
    }
  }
}
// 8. BERSIHKAN REGISTRY MANUAL (#BERSIHKAN / #CLEAR / #RESET)
else if (rawCmd === '#BERSIHKAN' || rawCmd === '#CLEAR' || rawCmd === '#RESET') {
  staticData.devices = {};
  reply = '🧹 *[REGISTRY PERANGKAT DIBERSIHKAN]*\nSemua riwayat perangkat lama telah dihapus.\n\nPerangkat yang aktif akan otomatis muncul kembali dalam beberapa detik saat mengirim sinkronisasi.';
}
// 9. PERINTAH TIDAK DIKENAL
else {
  reply = '❓ *[PERINTAH TIDAK DIKENAL]*\n\n' +
    `Perintah "${content}" tidak dikenali oleh Bot TUNTAS.\n\n` +
    '👉 Ketik *#QUERY* untuk melihat daftar lengkap perintah bot.';
}

return { json: { replyMessage: reply } };

const staticData = $getWorkflowStaticData('global');
const body = $json.body || {};

staticData.devices = staticData.devices || {};
staticData.pendingCommands = staticData.pendingCommands || {};

const pcName = String(body.pc || body.pc_name || 'PC 1').trim();

// Format waktu standar WITA
const waktuWita = body.waktu_lokal || (new Date().toLocaleTimeString('id-ID', { 
  timeZone: 'Asia/Makassar', 
  hour12: false 
}) + ' WITA');

// 1. Simpan telemetri status PC ini ke registry devices secara lengkap
if (body.pc || body.pc_name || body.status) {
  const deviceData = {
    pc: pcName,
    status: body.status || 'IDLE',
    statusLabel: body.statusLabel || body.status || 'IDLE',
    mode: body.modeLabel || body.mode || '-',
    progress: body.progress || body.progres || '0 / 0',
    persen: body.persen || '',
    nama_usaha: body.nama_usaha || '-',
    no_baris: body.no_baris || '-',
    successCount: body.successCount ?? body.sukses ?? 0,
    failedCount: body.failedCount ?? body.gagal ?? 0,
    skippedCount: body.skippedCount ?? body.dilewati ?? 0,
    queueRemaining: body.queueRemaining ?? body.sisa_antrian ?? 0,
    totalQueue: body.totalQueue ?? body.total_antrian ?? 0,
    serverHealth: body.serverHealth || body.server_health || 'Normal (1.0x)',
    message: body.message || body.text || '',
    updatedAt: waktuWita,
    lastSeen: Number(body.timestamp) || Date.now() // Stempel waktu aktif
  };

  staticData.devices[pcName] = deviceData;
  staticData.lastStatus = deviceData;
}

// 2. Ambil perintah khusus untuk PC ini (Pencocokan Cerdas)
let commandToSend = { action: 'NONE' };
let matchedCmdKey = null;

const pendingKeys = Object.keys(staticData.pendingCommands || {});
const cleanPc = pcName.toUpperCase().replace(/[\s\-_]/g, '');
const pcDigits = pcName.replace(/\D/g, '');

for (const pk of pendingKeys) {
  const cleanPk = pk.toUpperCase().replace(/[\s\-_]/g, '');
  const pkDigits = pk.replace(/\D/g, '');

  if (pk.toUpperCase() === pcName.toUpperCase() || cleanPk === cleanPc || (pcDigits && pkDigits && pcDigits === pkDigits)) {
    matchedCmdKey = pk;
    break;
  }
}

// Eksekusi perintah khusus PC ini
if (matchedCmdKey) {
  commandToSend = staticData.pendingCommands[matchedCmdKey];
  delete staticData.pendingCommands[matchedCmdKey];

  // Dukung RESUME, JEDA, STOP, dan RETRY_FAILED (#ULANG)
  if (commandToSend.action === 'RESUME' || commandToSend.action === 'LANJUT') {
    if (staticData.devices[pcName]) staticData.devices[pcName].status = 'RUNNING';
  } else if (commandToSend.action === 'RETRY_FAILED' || commandToSend.action === 'ULANG') {
    // Hanya ubah status menjadi RUNNING jika PC ini memang punya baris gagal
    if (staticData.devices[pcName] && Number(staticData.devices[pcName].failedCount) > 0) {
      staticData.devices[pcName].status = 'RUNNING';
    }
  } else if (commandToSend.action === 'PAUSE' || commandToSend.action === 'JEDA') {
    if (staticData.devices[pcName]) staticData.devices[pcName].status = 'PAUSED';
  } else if (commandToSend.action === 'STOP' || commandToSend.action === 'BERHENTI') {
    if (staticData.devices[pcName]) staticData.devices[pcName].status = 'STOPPED';
  }
}
// Jika ada perintah broadcast untuk SEMUA PC
else if (staticData.broadcastCommand) {
  staticData.executedBroadcasts = staticData.executedBroadcasts || {};
  const broadcastId = staticData.broadcastCommand.id;

  if (!staticData.executedBroadcasts[broadcastId]) {
    staticData.executedBroadcasts[broadcastId] = [];
  }

  if (!staticData.executedBroadcasts[broadcastId].includes(pcName)) {
    commandToSend = staticData.broadcastCommand;
    staticData.executedBroadcasts[broadcastId].push(pcName);

    // Pengaman ketat: jika perintah adalah RETRY_FAILED, jangan kirim ke PC yang memiliki 0 baris gagal
    if (commandToSend.action === 'RETRY_FAILED' || commandToSend.action === 'ULANG') {
      const fCount = Number(staticData.devices[pcName]?.failedCount || 0);
      if (fCount === 0) {
        commandToSend = { action: 'NONE' };
      } else if (staticData.devices[pcName]) {
        staticData.devices[pcName].status = 'RUNNING';
      }
    } else if (commandToSend.action === 'RESUME' || commandToSend.action === 'LANJUT') {
      if (staticData.devices[pcName]) staticData.devices[pcName].status = 'RUNNING';
    } else if (commandToSend.action === 'PAUSE' || commandToSend.action === 'JEDA') {
      if (staticData.devices[pcName]) staticData.devices[pcName].status = 'PAUSED';
    } else if (commandToSend.action === 'STOP' || commandToSend.action === 'BERHENTI') {
      if (staticData.devices[pcName]) staticData.devices[pcName].status = 'STOPPED';
    }
  }
}

return { json: { status: 'OK', command: commandToSend } };
